import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('onError rejection cause', () => {
  it('preserves a non-Error rejection as cause and rethrows it [specs/hal-engine-config-hooks/spec.md#8]', async () => {
    const reason = {code: 503};
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    let observed: Error | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {onError: async (_session, error) => void (observed = error)},
    });
    const session: ChatSession = {sessionId: 's', userId: 'u', entries: []};
    const thrown: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

    expect({isError: observed instanceof Error, cause: observed?.cause, thrown}).toEqual({
      isError: true,
      cause: reason,
      thrown: reason,
    });
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
